INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES (156, 119, '[[$table-three-col-without-top-bl7]]'), (156, 316, '[[$table-three-col-without-top-bl7]]'), (156, 1119, '[[$table-three-col-without-top-bl7]]'), (156, 168, '[[$table-three-col-without-top-bl7]]'), (156, 320, '[[$table-three-col-without-top-bl7]]'), (156, 1168, '[[$table-three-col-without-top-bl7]]');
-- Статья 635 «Tatuajul sprâncenelor…»: цены «TOP master / TOP trainer» → одна цена (как в таблицах страниц бровей: 1 100 / ретушь 400),
-- «команда специалистов, у каждого 5+ лет» → Ксения Кобылянская (10+ лет, 6 000+ процедур); H2 «Ce experiență au specialiștii…» → «…are masterul…»
UPDATE Impulse_Digital_X_site_content SET content = REPLACE(content, '<p>Tatuajul sprâncene efect pudrat, 3D/6D și microblading la TOP master costă 600 de lei, iar la TOP trainer – 800 lei. Tehnica fir cu fir și tehnica hybrid se realizează doar de specialiști de TOP și prețul este de 800 de lei. Retușul costă 200, respectiv 300 de lei, iar corecția după un alt specialist – 100% din prețul primei ședințe.', '<p>Tatuajul sprâncene efect pudrat, 3D/6D, microblading, tehnica fir cu fir și tehnica hybrid costă 1 100 de lei. Retușul costă 400 de lei, iar corecția după un alt specialist – 100% din prețul primei ședințe.') WHERE id = 635;
UPDATE Impulse_Digital_X_site_content SET content = REPLACE(content, '<h2>Ce experiență au specialiștii de la LBar?</h2>', '<h2>Ce experiență are masterul de la LBar?</h2>') WHERE id = 635;
UPDATE Impulse_Digital_X_site_content SET content = REPLACE(content, '<p>În studioul nostru de machiaj permanent activează o echipă de specialiști calificați, care dețin numeroase diplome și certificate de cursuri de formare profesională și perfecționare. Fiecare are cel puțin 5 ani de experiență și își îmbunătățește în mod constant abilitățile. LBar – o rețea de studiouri de elită în Kiev, Varșovia și București. Specialiștii noștri au realizat peste 5000 de ședințe de tatuaj sprâncene în diferite tehnici.</p>', '<p>În studioul nostru de machiaj permanent procedurile sunt efectuate de Ksenia Kobilianskaia — master internațional și Master Trainer, cu numeroase diplome și certificate de cursuri de formare profesională și perfecționare. Are peste 10 ani de experiență și peste 6 000 de proceduri realizate și își îmbunătățește în mod constant abilitățile. LBar – o rețea de studiouri de elită în Kiev, Varșovia și București.</p>') WHERE id = 635;
UPDATE Impulse_Digital_X_site_content SET content = REPLACE(content, 'suntem preocupați de siguranța clienților și a specialiștilor noștri.', 'suntem preocupați de siguranța clienților și a masterului.') WHERE id = 635;
UPDATE Impulse_Digital_X_site_content SET content = REPLACE(content, 'necesită cunoștințe de cromatică – specialiștii noștri sunt experți în acest domeniu.', 'necesită cunoștințe de cromatică – masterul nostru este expert în acest domeniu.') WHERE id = 635;
